// Asset loading. Models are embedded as base64 in dist/assets.js (generated by tools/build-assets.mjs)
// so the game still runs from file:// without a server.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

export const A = { models: {}, clips: {}, parts: {}, ready: false };

const MATS = { // material name in the gun pack -> PBR response
  Black: { c: 0x17191b, m: 0.35, r: 0.55 }, DarkMetal: { c: 0x2a2d31, m: 0.85, r: 0.42 }, Metal: { c: 0x60656b, m: 0.9, r: 0.35 }, LightMetal: { c: 0x9aa0a6, m: 0.95, r: 0.25 },
  LightMetal2: { c: 0x7e848a, m: 0.95, r: 0.3 }, DarkWood: { c: 0x5b391f, m: 0, r: 0.62 }, Wood: { c: 0x6e4826, m: 0, r: 0.6 }, Glass: { c: 0x0c1418, m: 0.9, r: 0.08 }, Main: { c: 0x1c1e20, m: 0.3, r: 0.6 },
  Green: { c: 0x3c4630, m: 0.1, r: 0.7 }, DarkGreen: { c: 0x2c3524, m: 0.1, r: 0.7 },
};
function tune(scene) {
  scene.traverse((o) => {
    if (!o.isMesh) return;
    o.castShadow = true;
    const fix = (m) => { const d = MATS[m.name]; if (d) { m.color.setHex(d.c); m.metalness = d.m; m.roughness = d.r; } else { m.metalness = Math.min(m.metalness, 0.3); m.roughness = Math.max(m.roughness, 0.6); } return m; };
    o.material = Array.isArray(o.material) ? o.material.map(fix) : fix(o.material);
  });
}
// Environment props: bake node transforms into geometry and switch to cheap Lambert materials so they can be instanced.
function bake(name, scene) {
  scene.updateMatrixWorld(true);
  const parts = [], box = new THREE.Box3();
  scene.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry.clone().applyMatrix4(o.matrixWorld), m = o.material, leaf = /Lea|Grass/.test(m.name);
    g.computeBoundingBox(); box.union(g.boundingBox);
    const mat = new THREE.MeshLambertMaterial({ map: m.map, color: m.map ? 0xffffff : m.color, alphaTest: leaf ? 0.45 : 0, side: leaf ? THREE.DoubleSide : THREE.FrontSide });
    if (/Light/.test(m.name)) { mat.emissive = new THREE.Color(m.name === 'BrakeLight' ? 0x300000 : 0x000000); }
    parts.push({ geo: g, mat, leaf });
  });
  A.parts[name] = { parts, box };
}
function decode(s) { const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u.buffer; }

export async function loadAssets(onProgress = () => {}) {
  const src = window.SP_ASSETS || {}, names = Object.keys(src), L = new GLTFLoader();
  let n = 0;
  for (const k of names) {
    const g = await new Promise((res, rej) => L.parse(decode(src[k]), '', res, rej));
    if (k === 'soldier') for (const c of g.animations) A.clips[c.name] = c; else if (k.startsWith('prop_')) bake(k.slice(5), g.scene); else tune(g.scene);
    A.models[k] = g.scene; onProgress(++n / names.length);
  }
  A.ready = true;
}

// Gun metadata, measured on the source models (model units, +X = muzzle). s = scale to metres.
export const GUN = {
  ak: { s: 0.162, grip: [0.02, 0.05], muzzle: [3.85, 0.58], sight: 0.9, rail: [0.7, 0.8], hand: [1.95, 0.42], eject: [0.9, 0.66] },
  m4: { s: 0.162, grip: [0.1, 0.05], muzzle: [3.6, 0.65], sight: 1.05, rail: [0.2, 0.93], hand: [1.8, 0.5], eject: [0.65, 0.68] },
  dmr: { s: 0.15, grip: [0.25, -0.1], muzzle: [5.2, 0.22], sight: 0.5, hand: [1.9, 0.05], eject: [0.6, 0.25], scope: [-0.22, 0.5] },
  shotgun: { s: 0.175, grip: [0.15, 0], muzzle: [3.8, 0.24], sight: 0.37, rail: [0.8, 0.33], hand: [2.2, -0.04], eject: [0.9, 0.2] },
  smg: { s: 0.16, grip: [-0.05, 0], muzzle: [2.25, 0.55], sight: 0.78, rail: [0.7, 0.72], hand: [1.45, 0.38], eject: [0.6, 0.5] },
  pistol: { s: 0.11, grip: [0, 0.1], muzzle: [1.45, 0.42], sight: 0.56, hand: [0.05, 0.02], eject: [0.5, 0.5] },
  carbine: { s: 0.162, grip: [0.15, 0.1], muzzle: [3.25, 0.62], sight: 0.9, hand: [2.0, 0.5], eject: [0.9, 0.66] },
};
// Returns a group in "weapon space": origin at the pistol grip, barrel along -Z, up +Y.
export function makeGun(id) {
  const d = GUN[id], g = new THREE.Group(), m = A.models['gun_' + id].clone(true);
  m.scale.setScalar(d.s); m.rotation.y = Math.PI / 2; m.position.set(0, -d.grip[1] * d.s, d.grip[0] * d.s);
  g.add(m); g.model = m; g.def = d;
  g.pt = (p, z = 0) => new THREE.Vector3(z * d.s, (p[1] - d.grip[1]) * d.s, -(p[0] - d.grip[0]) * d.s);
  g.muzzle = g.pt(d.muzzle);
  return g;
}
